-- 0005_payments.sql
-- Stage 8: payment persistence and wallet crediting (prepared, NOT applied).
--
-- This migration records payment attempts, stores provider events for replay
-- protection, and credits the wallet exactly once per successful payment. It
-- depends on 0004_wallet.sql (wallets, wallet_entries, wallet_credit).
--
-- Design notes:
--   * `payments.reference` is our own id, generated by the API before the
--     provider is called; the provider echoes it back.
--   * `payment_events.provider_event_id` is unique per provider, so a redelivered
--     webhook is a no-op instead of a second credit.
--   * Crediting is idempotent: the ledger entry id is derived from the payment
--     reference, so replaying the credit cannot double-pay.
--   * Only the service role (the Worker) may write these tables.
--
-- APPLY THIS ONLY AFTER OWNER APPROVAL. Nothing in the build applies it.

-- ---------------------------------------------------------------------------
-- Payments
-- ---------------------------------------------------------------------------

create table if not exists public.payments (
  reference text primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  provider text not null,
  amount_minor bigint not null check (amount_minor > 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  status text not null default 'pending'
    check (status in ('pending', 'success', 'failed', 'abandoned', 'refunded')),
  provider_reference text,
  authorization_url text,
  paid_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.payments is
  'One row per checkout attempt. Balances are never accepted from the browser; only the provider response, re-verified server-side, may change status.';

create index if not exists payments_user_created_idx on public.payments (user_id, created_at desc);
create index if not exists payments_status_idx on public.payments (status);

alter table public.payments enable row level security;

drop policy if exists "payments_select_own" on public.payments;
create policy "payments_select_own"
  on public.payments
  for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- No client insert/update/delete: the Worker writes these as service_role.
revoke all on public.payments from anon, authenticated;
grant select on public.payments to authenticated;

drop trigger if exists payments_touch_updated_at on public.payments;
create trigger payments_touch_updated_at
  before update on public.payments
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Provider events (replay protection)
-- ---------------------------------------------------------------------------

create table if not exists public.payment_events (
  id uuid primary key default gen_random_uuid(),
  provider text not null,
  provider_event_id text not null,
  type text not null,
  reference text,
  status text,
  payload jsonb,
  received_at timestamptz not null default now(),
  constraint payment_events_unique_event unique (provider, provider_event_id)
);

comment on table public.payment_events is
  'Every verified provider event. The unique (provider, provider_event_id) constraint rejects redelivered webhooks.';

alter table public.payment_events enable row level security;
-- No policies at all: only the service role can read or write provider events.

revoke all on public.payment_events from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Service-role functions
-- ---------------------------------------------------------------------------

-- Record or update a checkout attempt. Safe to call twice with the same reference.
create or replace function public.payment_record_attempt(
  p_reference text,
  p_user_id uuid,
  p_provider text,
  p_amount_minor bigint,
  p_currency text,
  p_authorization_url text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  insert into public.payments (reference, user_id, provider, amount_minor, currency, authorization_url)
  values (p_reference, p_user_id, p_provider, p_amount_minor, p_currency, p_authorization_url)
  on conflict (reference) do nothing;
end;
$$;

-- Store a verified provider event. A redelivery with the same event id is a no-op.
create or replace function public.payment_store_event(
  p_provider text,
  p_provider_event_id text,
  p_type text,
  p_reference text,
  p_status text,
  p_payload jsonb
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_inserted boolean;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  insert into public.payment_events (provider, provider_event_id, type, reference, status, payload)
  values (p_provider, p_provider_event_id, p_type, p_reference, p_status, p_payload)
  on conflict (provider, provider_event_id) do nothing;

  v_inserted := found;
  return v_inserted;
end;
$$;

-- Mark a payment successful and credit the wallet exactly once.
--
-- The amount and currency come from the stored payment row (written when the
-- checkout was created), never from the webhook payload. The ledger entry id is
-- derived from the payment reference, so a replayed event credits nothing.
create or replace function public.payment_settle(
  p_reference text,
  p_paid_at timestamptz default now()
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
  v_wallet_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  select * into v_payment from public.payments where reference = p_reference for update;
  if v_payment.reference is null then
    raise exception 'unknown payment' using errcode = 'no_data_found';
  end if;

  -- Already settled: nothing to do (idempotent).
  if v_payment.status = 'success' then
    return;
  end if;

  select id into v_wallet_id from public.wallets where user_id = v_payment.user_id;
  if v_wallet_id is null then
    insert into public.wallets (user_id, currency)
    values (v_payment.user_id, v_payment.currency)
    returning id into v_wallet_id;
  end if;

  -- Credit the wallet. The ledger entry id is derived from the payment reference,
  -- and wallet_credit ignores a duplicate id, so this is safe to retry.
  perform public.wallet_credit(
    v_wallet_id,
    'payment:' || v_payment.reference,
    v_payment.amount_minor,
    v_payment.currency,
    v_payment.reference
  );

  update public.payments
  set status = 'success', paid_at = coalesce(p_paid_at, now())
  where reference = p_reference;
end;
$$;

-- Mark a payment failed (no money moves).
create or replace function public.payment_fail(p_reference text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  update public.payments
  set status = 'failed'
  where reference = p_reference and status = 'pending';
end;
$$;

-- ---------------------------------------------------------------------------
-- Reconciliation
-- ---------------------------------------------------------------------------

-- A successful payment whose ledger credit is missing. Should always be empty;
-- a row here means a settlement failed between the payment update and the credit.
create or replace view public.payment_reconciliation as
select
  p.reference,
  p.user_id,
  p.amount_minor,
  p.currency,
  p.paid_at
from public.payments p
left join public.wallet_entries e
  on e.id = 'payment:' || p.reference
where p.status = 'success'
  and e.id is null;

comment on view public.payment_reconciliation is
  'Successful payments with no matching ledger credit. Any row is an alert.';

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------

revoke all on function public.payment_record_attempt(text, uuid, text, bigint, text, text) from public, anon, authenticated;
revoke all on function public.payment_store_event(text, text, text, text, text, jsonb) from public, anon, authenticated;
revoke all on function public.payment_settle(text, timestamptz) from public, anon, authenticated;
revoke all on function public.payment_fail(text) from public, anon, authenticated;

grant execute on function public.payment_record_attempt(text, uuid, text, bigint, text, text) to service_role;
grant execute on function public.payment_store_event(text, text, text, text, text, jsonb) to service_role;
grant execute on function public.payment_settle(text, timestamptz) to service_role;
grant execute on function public.payment_fail(text) to service_role;